export function classifyPerfectNumber(n) {
    if (n <= 0)
        throw new Error('Positive integer required');
    let sum = 0;
    for (let d = 1; d <= Math.floor(n / 2); d++)
        if (n % d === 0)
            sum += d;
    return sum === n ? 'perfect' : sum > n ? 'abundant' : 'deficient';
}
